type point struct {
	x float64
	y float64
}

func normalizePoints(pts [4]core.PdfPoint) [4]core.PdfPoint {
	sorted := make([]point, 4)
	for i, pt := range pts {
		sorted[i] = point{x: pt.X, y: pt.Y}
	}
	for i := 0; i < len(sorted)-1; i++ {
		for j := i + 1; j < len(sorted); j++ {
			if sorted[j].x < sorted[i].x || (sorted[j].x == sorted[i].x && sorted[j].y < sorted[i].y) {
				sorted[i], sorted[j] = sorted[j], sorted[i]
			}
		}
	}
	var res [4]core.PdfPoint
	for i, sp := range sorted {
		res[i] = core.NewPdfPoint(sp.x, sp.y)
	}
	return res
}

func pointsEqual(a, b [4]core.PdfPoint, tol float64) bool {
	na := normalizePoints(a)
	nb := normalizePoints(b)
	for i := range na {
		if math.Abs(na[i].X-nb[i].X) > tol || math.Abs(na[i].Y-nb[i].Y) > tol {
			return false
		}
	}
	return true
}

func TestPdfRectangleRotate360(t *testing.T) {
	rect := core.NewPdfRectangleFloat(10, 10, 20, 20)
	result := rect.Rotate(360)
	if !result.Equals(rect) {
		t.Errorf("Rotate360: got %v, want %v", result, rect)
	}
}

func TestPdfRectangleRotate90(t *testing.T) {
	rect := core.NewPdfRectangleFloat(0, 0, 10, 20)
	result := rect.Rotate(90)
	expectedArea := rect.Area()
	if math.Abs(result.Area()-expectedArea) > 0.001 {
		t.Errorf("Rotate90 area: got %.6f, want %.6f", result.Area(), expectedArea)
	}
}

func TestPdfRectangleRotate180(t *testing.T) {
	unitRect := core.NewPdfRectangleFloat(0, 0, 1, 1)
	result := unitRect.Rotate(180)

	expectedBL := core.NewPdfPoint(0, 0)
	expectedBR := core.NewPdfPoint(-1, 0)
	expectedTL := core.NewPdfPoint(0, -1)
	expectedTR := core.NewPdfPoint(-1, -1)

	tol := 1e-6
	if math.Abs(result.BottomLeft.X-expectedBL.X) > tol || math.Abs(result.BottomLeft.Y-expectedBL.Y) > tol {
		t.Errorf("BottomLeft: got %v, want %v", result.BottomLeft, expectedBL)
	}
	if math.Abs(result.BottomRight.X-expectedBR.X) > tol || math.Abs(result.BottomRight.Y-expectedBR.Y) > tol {
		t.Errorf("BottomRight: got %v, want %v", result.BottomRight, expectedBR)
	}
	if math.Abs(result.TopLeft.X-expectedTL.X) > tol || math.Abs(result.TopLeft.Y-expectedTL.Y) > tol {
		t.Errorf("TopLeft: got %v, want %v", result.TopLeft, expectedTL)
	}
	if math.Abs(result.TopRight.X-expectedTR.X) > tol || math.Abs(result.TopRight.Y-expectedTR.Y) > tol {
		t.Errorf("TopRight: got %v, want %v", result.TopRight, expectedTR)
	}
	if math.Abs(result.Width-1) > tol || math.Abs(result.Height-1) > tol {
		t.Errorf("Size: got (%.6f, %.6f), want (1, 1)", result.Width, result.Height)
	}
	if math.Abs(math.Abs(result.Rotation())-180) > tol {
		t.Errorf("Rotation: got %.6f, want ~180", result.Rotation())
	}
}

